<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';auth();require_once __DIR__.'/experiments.php';require_once __DIR__.'/ai_proposals.php';
$h=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$recipes=query('SELECT id,name,flour_g,water_g,salt_g,oil_g,honey_g,yeast_g FROM recipes ORDER BY name')->fetchAll();
$pending=lab_proposals(100);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10151c"><title>Pizza Lab · AI Experiment Proposals</title><link rel="stylesheet" href="assets/style.css?v=1.5.3"><style>.pwrap{max-width:1180px;margin:auto;padding:clamp(16px,4vw,45px)}.pgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px}.pform{display:grid;gap:12px;max-width:750px}.proposal{border:1px solid #46505d;border-radius:12px;padding:18px;margin:14px 0;word-wrap:break-word}.proposal details{margin:12px 0}.proposal summary{cursor:pointer}.pmessage{position:sticky;top:0;z-index:2;padding:12px;background:#282e39;border-radius:8px;display:none}.pstatus{font-weight:bold;text-transform:capitalize}</style></head><body><main class="pwrap"><p class="overline">RECIPE LAB</p><h1>AI Experiment Proposals</h1><p>Claude suggests one measurable recipe variation. Review the proposed grams and process guidance before approving. Approval creates a <b>new experimental recipe</b> and a linked experiment; it does not change the source recipe or an existing dough batch.</p><p><a href="index.php">← Workspace</a> · <a href="gallery.php">Photo gallery</a></p><div id="feedback" class="pmessage" role="status" aria-live="polite"></div><section class="panel"><h2>Request a proposed variation</h2><form id="requestProposal" class="pform"><label>Source recipe<select name="source_recipe_id" required><?php foreach($recipes as $r):?><option value="<?=$h($r['id'])?>"><?=$h($r['name'])?> (<?=$h($r['flour_g']??'Unknown')?> g flour)</option><?php endforeach;?></select></label><label>Main quality target<select name="target_metric"><option value="crispness">More crispness</option><option value="oven_spring">More oven spring</option><option value="bottom_color">Deeper underside color</option><option value="bake_time">Improved bake time</option></select></label><label>Your goal<textarea name="goal" required minlength="8" maxlength="500" rows="3" placeholder="Increase oven spring at 72 hours without weakening gluten or increasing scorching"></textarea></label><button class="primary" type="submit">Generate pending proposal with Claude</button><p class="muted small">Requires the Super Admin’s Claude API key. Analysis is initiated only when you submit and incurs API usage. Team members can review and approve or reject proposals.</p></form></section><section class="panel mt"><h2>Review queue</h2><?php if(!$pending):?><p class="muted">No proposals yet. Generate a variation to begin a review.</p><?php endif;?><?php foreach($pending as $p):$delta=json_decode($p['proposed_changes_json'],true)?:[];?><article class="proposal"><div class="between"><strong><?=$h($p['title'])?></strong><span class="pill pstatus"><?=$h($p['status'])?></span></div><p class="small muted">Source: <?=$h($p['source_recipe_name'])?> · Requested by <?=$h($p['requested_by'])?> · <?=$h($p['created_at'])?></p><p><b>Hypothesis:</b> <?=$h($p['hypothesis'])?></p><p><b>Proposed ingredient values (grams):</b></p><table class="compact-table"><thead><tr><th>Ingredient</th><th>Current</th><th>Proposed</th><th>Change</th></tr></thead><tbody><?php foreach($delta as $key=>$value):?><tr><td><?=$h(str_replace('_g','',str_replace('_',' ',$key)))?></td><td><?=$h($p["base_".$key]??"Unknown")?> g</td><td><?=$h($value)?> g</td><td><?=$h(isset($p["base_".$key])?round((float)$value-(float)$p["base_".$key],2):"Unknown")?> g</td></tr><?php endforeach;?></tbody></table><details><summary>Evidence and mixing instructions</summary><p><b>Evidence basis:</b> <?=$h($p['evidence_basis'])?></p><p><b>Suggested process changes (not automatically applied):</b> <?=$h($p['step_guidance'])?></p></details><?php if($p['status']==='pending'):?><div class="flex"><button class="primary" type="button" data-decision="approve" data-id="<?=$h($p['id'])?>">Approve and create variation</button><button type="button" data-decision="reject" data-id="<?=$h($p['id'])?>">Reject</button></div><?php else:?><p class="muted">Decided by <?=$h($p['decided_by']??'Unknown')?> on <?=$h($p['decided_at']??'Unknown')?><?php if($p['approved_experiment_id']):?> · Experiment #<?=$h($p['approved_experiment_id'])?><?php endif;?></p><?php endif;?></article><?php endforeach;?></section></main><script>const csrf=<?=json_encode(csrf())?>;const notice=(msg,bad=false)=>{let x=document.getElementById('feedback');x.textContent=msg;x.style.display='block';x.style.background=bad?'#5e2929':'#244b43';x.scrollIntoView({behavior:'smooth',block:'start'});};async function send(action,values){let response=await fetch('api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action,...values})});let result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Request failed');return result;}document.querySelector('#requestProposal').addEventListener('submit',async e=>{e.preventDefault();let form=e.currentTarget;let btn=form.querySelector('button');btn.disabled=true;notice('Requesting Claude proposal…');try{let result=await send('generateProposal',Object.fromEntries(new FormData(form)));notice('Saved pending proposal #'+result.id+'. Reloading review queue.');location.reload();}catch(err){notice(err.message,true);}finally{btn.disabled=false;}});document.addEventListener('click',async e=>{let btn=e.target.closest('[data-decision]');if(!btn)return;let decision=btn.dataset.decision;let id=btn.dataset.id;if(!confirm(decision==='approve'?'Approve this proposal and create a NEW experimental recipe?':'Reject this proposed variation?'))return;btn.disabled=true;try{let result=await send('decideProposal',{id,decision});notice('Proposal '+result.status+'.');location.reload();}catch(err){notice(err.message,true);}finally{btn.disabled=false;}});</script></body></html>